mapper.select:
SELECT a.id AS "id", a.rec_type AS "recType", a.parent_id AS "parentId", a.tree_sort AS "treeSort", a.tree_leaf AS "treeLeaf", a.parent_name AS "parentName", a.name AS "name", a.code AS "code", a.device_type AS "deviceType", a.ip AS "ip", a.rtsp_port AS "rtspPort", a.admin_user AS "adminUser", a.admin_password AS "adminPassword", a.rtsp_uri AS "rtspUri", a.channel AS "channel", a.subtype AS "subtype", a.load_source AS "loadSource", a.stream_url AS "streamUrl", a.camera_index_code AS "cameraIndexCode", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks", a.corp_code AS "corpCode", a.corp_name AS "corpName" FROM js_sys_monitor_device_info a
a.status = '0'
AND a.rec_type = #{recType}
AND a.name = #{name}
AND a.device_type = #{deviceType}
AND a.parent_id = #{parentId}
ORDER BY a.update_date DESC
